<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/ShopAccessFixture.php';
require_once __DIR__.'/PortalActionAcceptanceFixture.php';
use DigiForge\Database\Tables;

final class PortalReviewConfirmationAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();ShopAccessFixture::reset();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));ShopAccessFixture::authorizeActor(get_current_user_id(),['digital','personalized_pod','standard_pod','jewelry'],DigiForge\Core\Capabilities::ALL);}
 private function candidate(string $shop='digital'):array {$candidate=(new DigiForge\Research\Repository())->createCandidate(['shop_key'=>$shop,'title'=>'Confirmation fixture '.wp_generate_uuid4(),'signals'=>['demand'=>85]]);self::assertNotWPError($candidate);return $candidate;}
 public function testMissingExplicitConfirmationCannotReviewEvenWithValidOperatorAndNonce():void {
  $candidate=$this->candidate();PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',['candidate_id'=>$candidate['id'],'decision'=>'APPROVED'],true,false);global $wpdb;self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));
 }
 private function body(array $candidate,string $decision='APPROVED'):array {$context=DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_review_research',(int)$candidate['id'],null,['decision'=>$decision]);self::assertNotWPError($context);return ['candidate_id'=>$candidate['id'],'decision'=>$decision,'df_confirm_review'=>'1','df_confirmation_shop'=>$context['shop'],'df_confirmation_nonce'=>$context['confirmation_nonce'],'df_confirmation_issued_at'=>$context['issued_at'],'df_confirmation_tokens'=>[$decision=>$context['token']]];}
 public function testActualConfirmationShowsTargetCurrentEvidenceAndPermitsOnlyChosenLocalDecision():void {
  $candidate=$this->candidate();$body=$this->body($candidate);$get=$_GET;try{$_GET=['df_view'=>'approvals','df_shop'=>'digital'];$html=(new DigiForge\Portal\Portal())->render();self::assertStringContainsString('Research candidate #'.$candidate['id'],$html);self::assertStringContainsString('Shop: digital',$html);self::assertStringContainsString('Current evidence SHA-256',$html);self::assertStringContainsString('name="df_confirm_review"',$html);self::assertStringContainsString('value="1" required',$html);self::assertStringContainsString('name="df_confirmation_tokens[APPROVED]"',$html);self::assertStringContainsString('No publishing, provider production, fulfillment or money movement',$html);$this->capture('confirmation-research.html',$html);}finally{$_GET=$get;}
  PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,false,false);global $wpdb;self::assertSame('APPROVED',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 private function capture(string $name,string $html):void {$directory=getenv('DF_CONFIRMATION_FIXTURE_DIR');if(is_string($directory)&&$directory!==''&&is_dir($directory))self::assertSame(strlen($html),file_put_contents($directory.'/'.$name,$html));}
 public function testActualRenderedRejectChoiceUsesSameFreshConfirmationNonceAndRecordsOnlyRejection():void {
  $candidate=$this->candidate();$get=$_GET;try{$_GET=['df_view'=>'approvals','df_shop'=>'digital'];$html=(new DigiForge\Portal\Portal())->render();}finally{$_GET=$get;}$dom=new DOMDocument();@$dom->loadHTML($html);$xpath=new DOMXPath($dom);$forms=$xpath->query('//form[input[@name="action" and @value="digiforge_portal_review_research"] and input[@name="candidate_id" and @value="'.$candidate['id'].'"]]');self::assertSame(1,$forms->length);$pairs=[];foreach($xpath->query('.//input[@type="hidden"]',$forms->item(0))as $input)$pairs[]=urlencode($input->getAttribute('name')).'='.urlencode($input->getAttribute('value'));parse_str(implode('&',$pairs),$body);$body['decision']='REJECTED';$body['df_confirm_review']='1';PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,false,false);global $wpdb;self::assertSame('REJECTED',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));
 }
 public function testDurableLocalAcknowledgementIsOneUseAndNeverClaimsAReviewOutcomeOrExecutionPermit():void {
  $candidate=$this->candidate();$body=$this->body($candidate);$receipt=DigiForge\Portal\ReviewConfirmation::accept('digiforge_portal_review_research',(int)$candidate['id'],$body);self::assertNotWPError($receipt);self::assertTrue($receipt['confirmation_validated']);self::assertFalse($receipt['decision_recorded']);self::assertFalse($receipt['external_execution_authorized']);self::assertWPError(DigiForge\Portal\ReviewConfirmation::accept('digiforge_portal_review_research',(int)$candidate['id'],$body));global $wpdb;$raw=$wpdb->get_var($wpdb->prepare('SELECT context FROM '.Tables::audit_log().' WHERE event_type=%s AND object_id=%s','portal_review_confirmation_accepted',$receipt['acknowledgement_hash']));self::assertIsString($raw);self::assertStringNotContainsString($body['df_confirmation_tokens']['APPROVED'],$raw);self::assertStringNotContainsString($body['df_confirmation_nonce'],$raw);self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));$fresh=$this->body($candidate);self::assertNotSame($body['df_confirmation_nonce'],$fresh['df_confirmation_nonce']);self::assertNotWPError(DigiForge\Portal\ReviewConfirmation::accept('digiforge_portal_review_research',(int)$candidate['id'],$fresh));
 }
 public function testOneIssuedNonceCannotAcknowledgeOppositeChoiceWithoutABusinessMutation():void {
  $candidate=$this->candidate();$action='digiforge_portal_review_research';$id=(int)$candidate['id'];$approved=$this->body($candidate);
  $rejected=DigiForge\Portal\ReviewConfirmation::inspect($action,$id,'digital',['decision'=>'REJECTED'],['confirmation_nonce'=>$approved['df_confirmation_nonce'],'issued_at'=>$approved['df_confirmation_issued_at']]);self::assertNotWPError($rejected);
  $body=array_replace($approved,['decision'=>'REJECTED','df_confirmation_tokens'=>['REJECTED'=>$rejected['token']]]);
  self::assertTrue(DigiForge\Portal\ReviewConfirmation::verify($action,$id,$body));self::assertNotWPError(DigiForge\Portal\ReviewConfirmation::accept($action,$id,$approved));
  global $wpdb;self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$id)));
  $second=DigiForge\Portal\ReviewConfirmation::accept($action,$id,$body);self::assertWPError($second);self::assertSame('portal_confirmation_replay',$second->get_error_code());
  self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$id)));
 }
 public function testAuditFailureAndExpiredAcknowledgementCannotChangeReviewState():void {
  $candidate=$this->candidate();$body=$this->body($candidate);global $wpdb;$table=Tables::audit_log();$fail=static fn(string $sql):string=>str_starts_with($sql,'INSERT INTO `'.$table.'`')&&str_contains($sql,'portal_review_confirmation_accepted')?'INSERT INTO missing_local_confirmation_audit (id) VALUES (1)':$sql;add_filter('query',$fail);try{PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);}finally{remove_filter('query',$fail);}$body['df_confirmation_issued_at']=time()-901;PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));
 }
 public function testDanglingOrConcurrentlyChangedSourceFactsCannotGainAcknowledgedApproval():void {
  $candidate=$this->candidate();$body=$this->body($candidate);global $wpdb;self::assertSame(1,$wpdb->insert(Tables::research_candidate_evidence(),['candidate_id'=>$candidate['id'],'evidence_id'=>99999999,'created_at'=>current_time('mysql',true)]));self::assertWPError(DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_review_research',(int)$candidate['id'],'digital',['decision'=>'APPROVED']));PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);
  $other=$this->candidate();$body=$this->body($other);$reads=0;$changed=false;$race=function(string $sql)use(&$reads,&$changed,$other,$wpdb):string{if(str_contains($sql,'SELECT ce.evidence_id,e.*')&&str_contains($sql,'ce.candidate_id='.$other['id'])){if(++$reads===2&&!$changed){$changed=true;$wpdb->update(Tables::research_candidates(),['summary'=>'Concurrent changed source summary'],['id'=>$other['id']]);}}return $sql;};add_filter('query',$race);try{PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);}finally{remove_filter('query',$race);}self::assertTrue($changed);self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$other['id'])));
 }
 public function testForgedUncheckedSwappedTargetDecisionAndShopCannotConsumeAnotherConfirmation():void {
  $candidate=$this->candidate();$other=$this->candidate('jewelry');$valid=$this->body($candidate);$cases=[];$cases[]=array_replace($valid,['df_confirm_review'=>'0']);$cases[]=array_replace($valid,['df_confirmation_tokens'=>['APPROVED'=>str_repeat('0',64)]]);$cases[]=array_replace($valid,['candidate_id'=>$other['id']]);$cases[]=array_replace($valid,['decision'=>'REJECTED','df_confirmation_tokens'=>['REJECTED'=>$valid['df_confirmation_tokens']['APPROVED']]]);$cases[]=array_replace($valid,['df_confirmation_shop'=>'jewelry']);$cases[]=array_replace($valid,['candidate_id'=>$candidate['id'].'junk']);
  foreach($cases as $body)PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);global $wpdb;foreach([$candidate,$other]as $row)self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$row['id'])));
 }
 public function testChangedCandidateOrLinkedSourceFactRequiresFreshConfirmation():void {
  $repo=new DigiForge\Research\Repository();$source=$repo->createSource(['shop_key'=>'digital','name'=>'Confirmation source','source_type'=>'manual']);self::assertNotWPError($source);$observation=$repo->ingest(['source_id'=>$source['id'],'title'=>'Exact signed local source']);self::assertNotWPError($observation);$fact=$repo->addEvidence((int)$observation['id'],['value'=>'Original fact']);self::assertNotWPError($fact);$candidate=$this->candidate();self::assertTrue($repo->linkEvidence((int)$candidate['id'],(int)$fact['id']));$body=$this->body($candidate);global $wpdb;self::assertSame(1,$wpdb->update(Tables::research_evidence(),['value'=>'Changed fact'],['id'=>$fact['id']]));PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);$fresh=$this->body($candidate);self::assertNotSame($body['df_confirmation_tokens'],$fresh['df_confirmation_tokens']);self::assertSame(1,$wpdb->update(Tables::research_candidates(),['score'=>12],['id'=>$candidate['id']]));PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$fresh,true,false);self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));
 }
 public function testOtherAuthenticatedActorCannotReuseTokenAndNonceCapabilityGuardsStillRunFirst():void {
  $first=get_current_user_id();$second=self::factory()->user->create(['role'=>'administrator']);ShopAccessFixture::authorizeActor($second,['digital'],['manage_digiforge_research']);wp_set_current_user($first);$candidate=$this->candidate();$body=$this->body($candidate);wp_set_current_user($second);PortalActionAcceptanceFixture::invoke('REVIEW_ACTION',$body,true,false);wp_set_current_user($first);$post=$_POST;$request=$_REQUEST;$die=static fn()=>static function():never{throw new RuntimeException('confirmation-access-denied');};add_filter('wp_die_handler',$die);try{foreach([$first,0]as $actor){wp_set_current_user($actor);$_POST=$_REQUEST=$body+['_wpnonce'=>'invalid'];try{(new DigiForge\Portal\Portal())->review();self::fail('Nonce/capability must deny.');}catch(RuntimeException $error){self::assertSame('confirmation-access-denied',$error->getMessage());}}}finally{remove_filter('wp_die_handler',$die);$_POST=$post;$_REQUEST=$request;wp_set_current_user($first);}global $wpdb;self::assertSame('PENDING',$wpdb->get_var($wpdb->prepare('SELECT review_status FROM '.Tables::research_candidates().' WHERE id=%d',$candidate['id'])));
 }
 public function testOrderSupportConfirmationBindsStoredLinesAndSelectedShopWithoutProductionAuthority():void {
  $repo=new DigiForge\Orders\Repository();$order=$repo->createOrder(['shop_reference'=>'personalized_pod','environment'=>'sandbox']);self::assertNotWPError($order);global $wpdb;$now=current_time('mysql',true);self::assertSame(1,$wpdb->insert(Tables::order_line_items(),['order_id'=>$order['id'],'product_version_id'=>1,'listing_id'=>2,'provider_mapping_id'=>3,'quantity'=>1,'currency'=>'USD','validation_status'=>'VALIDATED','created_at'=>$now,'updated_at'=>$now]));$context=DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_replacement_request',(int)$order['id'],'personalized_pod');self::assertNotWPError($context);self::assertWPError(DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_replacement_request',(int)$order['id'],'jewelry'));$get=$_GET;try{$_GET=['df_view'=>'orders','df_shop'=>'personalized_pod'];$this->capture('confirmation-order.html',(new DigiForge\Portal\Portal())->render());}finally{$_GET=$get;}$body=['order_id'=>$order['id'],'shop_key'=>'personalized_pod','request_key'=>'confirmation-order','df_confirm_review'=>'1','df_confirmation_shop'=>'personalized_pod','df_confirmation_nonce'=>$context['confirmation_nonce'],'df_confirmation_issued_at'=>$context['issued_at'],'df_confirmation_tokens'=>['REVIEW'=>$context['token']]];self::assertSame(1,$wpdb->update(Tables::order_line_items(),['quantity'=>2],['order_id'=>$order['id']]));PortalActionAcceptanceFixture::invoke('REPLACEMENT_REQUEST_ACTION',$body,true,false);$cases=array_filter((new DigiForge\Orders\ReplacementReviewRepository())->snapshot('personalized_pod')['items'],static fn(array $case):bool=>(int)$case['order_id']===(int)$order['id']);self::assertSame([],array_values($cases));$fresh=DigiForge\Portal\ReviewConfirmation::inspect('digiforge_portal_replacement_request',(int)$order['id'],'personalized_pod');self::assertNotWPError($fresh);$body['df_confirmation_tokens']['REVIEW']=$fresh['token'];$body['df_confirmation_nonce']=$fresh['confirmation_nonce'];$body['df_confirmation_issued_at']=$fresh['issued_at'];PortalActionAcceptanceFixture::invoke('REPLACEMENT_REQUEST_ACTION',$body,false,false);self::assertSame('RECEIVED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$order['id'])));self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public static function protectedReviews():array {return array_map(static fn(string $constant):array=>[$constant],['REVIEW_ACTION','DEVELOP_ACTION','LISTING_REVIEW_ACTION','POD_RENDER_REVIEW_ACTION','POD_PACKAGE_REVIEW_ACTION','MASTER500_ACCEPTANCE_ACTION','PERSONALIZATION_REVIEW_ACTION','OWNERSHIP_REVIEW_ACTION','REPLACEMENT_REQUEST_ACTION','REPLACEMENT_DECISION_ACTION','DRAFT_QA_REVIEW_ACTION']);}
 /** @dataProvider protectedReviews */
 public function testEveryExistingHighRiskPortalHandlerRequiresExplicitConfirmationBeforeBusinessWrites(string $constant):void {
  $portal=new DigiForge\Portal\Portal();$action=(new ReflectionClass($portal))->getConstant($constant);$definition=DigiForge\Portal\ReviewConfirmation::definition($action);self::assertNotNull($definition);$body=[$definition[1]=>1,'shop'=>'digital','shop_key'=>'digital','request_key'=>'unconfirmed-fixture'];if($definition[5]!==[])$body['decision']=$definition[5][0];$mutations=[];$observe=static function(string $sql)use(&$mutations):string{if(preg_match('/^\s*(INSERT|UPDATE|DELETE|REPLACE)\b/i',$sql)&&str_contains($sql,'digiforge_'))$mutations[]=$sql;return $sql;};add_filter('query',$observe);try{PortalActionAcceptanceFixture::invoke($constant,$body,true,false);}finally{remove_filter('query',$observe);}self::assertSame([],$mutations);
 }
 public function testDraftQaTwoStepNativePreviewShowsChosenAssertionsAndRejectsAlteredChecksBeforeRecording():void {
  require_once __DIR__.'/DraftQaWorkflowAcceptanceTest.php';$fixtureCase=new DraftQaWorkflowAcceptanceTest();$builder=new ReflectionMethod($fixtureCase,'fixture');$builder->setAccessible(true);$fixture=$builder->invoke($fixtureCase);$checks=array_fill_keys(['title','description','seo','media','pricing','policy','personalization'],'PASS');$portal=new DigiForge\Portal\Portal();$action=(new ReflectionClass($portal))->getConstant('DRAFT_QA_PREVIEW_ACTION');$post=$_POST;$request=$_REQUEST;$get=$_GET;try{$_POST=$_REQUEST=['create_operation_id'=>$fixture['create'],'shop_key'=>'digital','checks'=>$checks,'_wpnonce'=>wp_create_nonce($action)];ob_start();$portal->previewDraftQa();$html=(string)ob_get_clean();}finally{$_POST=$post;$_REQUEST=$request;$_GET=$get;}self::assertStringContainsString('Confirm the exact draft and chosen assertions',$html);self::assertStringContainsString('Human Title assertion: PASS',$html);self::assertStringContainsString('Marketplace draft QA review #'.$fixture['create'],$html);$this->capture('confirmation-draft-qa.html',$html);
  $dom=new DOMDocument();@$dom->loadHTML($html);$xpath=new DOMXPath($dom);$forms=$xpath->query('//form[input[@name="action" and @value="digiforge_portal_draft_qa_review"]]');self::assertSame(1,$forms->length);$pairs=[];foreach($xpath->query('.//input[@type="hidden"]',$forms->item(0))as $input)$pairs[]=urlencode($input->getAttribute('name')).'='.urlencode($input->getAttribute('value'));parse_str(implode('&',$pairs),$body);$body['df_confirm_review']='1';$tampered=$body;$tampered['checks']['title']='FAIL';PortalActionAcceptanceFixture::invoke('DRAFT_QA_REVIEW_ACTION',$tampered,true,false);$repo=new DigiForge\Listings\DraftQaReviewRepository();self::assertWPError($repo->verify($fixture['intent'],$fixture['package'],'1234'));PortalActionAcceptanceFixture::invoke('DRAFT_QA_REVIEW_ACTION',$body,false,false);$record=$repo->verify($fixture['intent'],$fixture['package'],'1234');self::assertNotWPError($record);self::assertFalse($record['publish_authorized']);self::assertFalse($record['commercial_semantic_truth_certified']);PortalActionAcceptanceFixture::invoke('DRAFT_QA_REVIEW_ACTION',$body,true,false);self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
